-- Terokkar Forest: creature abilities
-- Most of the zone's creatures (the Arakkoa, the Bonechewer and Shadowmoon orcs, the Lost Ones, the ethereals and wildlife) had no
-- AI or ran classic rows: port their abilities from the classic (AzerothCore) data, falling back to the Cataclysm data; rows
-- needing events, actions or action lists LoA lacks are left out, and AzerothCore's range and area events are converted. The
-- creatures no reference scripts cast their sniffed spells (creature_template spell1-8).

SET @ENTRIES := '17088,18449,18482,18483,18670,18686,18689,21636,21651,21652,21660,21787,21849,21912,21985,22038,22045,22199,22452,23066,23067,23068,23161,23165,23219,23257,23619,23623,23624,23625,23626,24920';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '15241,18475,18973,19000,19002,19501,21244,21245,21638,21724,22407,23205,23207,51908';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
